#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

template <typename scalar_t>
__global__ void avg_pool1d_kernel(
    const scalar_t* __restrict__ input,
    scalar_t* __restrict__ output,
    const int N,
    const int C,
    const int in_len,
    const int out_len,
    const int kernel_size,
    const int stride,
    const int padding)
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * C * out_len;
    if (idx >= total) return;

    // decode indices
    int n = idx / (C * out_len);
    int rem = idx % (C * out_len);
    int c = rem / out_len;
    int t = rem % out_len;          // output position

    int start = t * stride - padding;   // first input index for this window
    float sum = 0.0f;                    // accumulate in fp32

    for (int k = 0; k < kernel_size; ++k) {
        int in_idx = start + k;
        if (in_idx >= 0 && in_idx < in_len) {
            sum += static_cast<float>(input[(n * C + c) * in_len + in_idx]);
        }
        // else: padding contributes zero
    }
    float avg = sum / static_cast<float>(kernel_size);
    output[idx] = __float2half(avg);
}

torch::Tensor avg_pool1d_forward(
    torch::Tensor input,
    int64_t kernel_size,
    int64_t stride,
    int64_t padding)
{
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(input.dtype() == torch::kHalf, "input must be torch.float16");
    TORCH_CHECK(input.dim() == 3, "input must be 3‑D (N, C, L)");

    auto N = input.size(0);
    auto C = input.size(1);
    auto in_len = input.size(2);

    int64_t out_len = (in_len + 2 * padding - kernel_size) / stride + 1;
    TORCH_CHECK(out_len > 0, "output length must be positive");

    auto output = torch::empty({N, C, out_len}, input.options());

    const int threads = 256;
    const int total = N * C * out_len;
    const int blocks = (total + threads - 1) / threads;

    AT_DISPATCH_HALF_TYPES(input.scalar_type(), "avg_pool1d_kernel", ([&] {
        avg_pool1d_kernel<scalar_t><<<blocks, threads>>>(
            input.data_ptr<scalar_t>(),
            output.data_ptr<scalar_t>(),
            N,
            C,
            in_len,
            out_len,
            static_cast<int>(kernel_size),
